/**
 * Sound design.
 *
 * MUSIC_BED is the client's backsound "bumper opening lighting show.mp3"
 * (public/audio/source/), edited to exactly 60 s by scripts/edit_backsound.sh.
 * Visual beats in src/config/timeline.ts are placed on its accents.
 *
 * SOUND_CUES are light original SFX layered on top (procedurally generated by
 * scripts/generate_audio.py, no samples). They are mixed low so the music
 * leads; set `enabled: false` to mute any of them.
 */
export type SoundCue = {
  id: string;
  at: number; // seconds
  file: string; // relative to public/
  volume: number; // 0..1
  label: string;
  enabled: boolean;
};

export const MUSIC_BED = {
  file: "audio/backsound_60s.wav",
  volume: 0.82,
  enabled: true,
  fadeOutSeconds: 0.4,
};

